                updates.rank = nextRank;

                // Set rank value immediately for updates
                const rankMap: Record<Rank, number> = { 'Legend': 4, 'Gold': 3, 'Silver': 2, 'Bronze': 1 };
                updates.rankValue = rankMap[nextRank];
