                id: newBattleId,
                mode: 'standard', // Friend battles standard by default
                player1: { 
                    uid: incomingInvite.fromUid, 
                    username: opponentProfile?.username || 'Opponent', 
                    avatar: opponentProfile?.avatar || null,
